function validate(input) {
  const [{ Products = [] }] = input;
  const seen = new Set();
  for (const [product, price, date] of Products) {
    if (product === null || price === null || date === null) return 'Every column of Products is required.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `change_date ${date} is not YYYY-MM-DD.`;
    const key = `${product}|${date}`;
    if (seen.has(key)) return `Product ${product} changes price twice on ${date}.`;
    seen.add(key);
  }
  return null;
}

