function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  // offset 0 is 2019-08-16; negative offsets are earlier days.
  const day = offset => new Date(Date.UTC(2019, 7, 16 + offset)).toISOString().slice(0, 10);
  const Products = [];
  const used = new Set();
  const add = (product, price, offset) => {
    const date = day(offset);
    if (used.has(`${product}|${date}`)) return;
    used.add(`${product}|${date}`);
    Products.push([product, price, date]);
  };
  if (size === 'small') {
    const offsets = [-200, -2, -1, 0, 1, 2];
    const prices = [5, 10, 20, 30, 35, 50, 65];
    const products = 1 + pick(4), rows = pick(9);
    for (let i = 0; i < rows; i++) add(1 + pick(products), prices[pick(prices.length)], offsets[pick(offsets.length)]);
  } else {
    for (let i = 0; i < 2000; i++) add(1 + pick(400), 1 + pick(200), pick(60) - 40);
  }
  return [{ Products }];
}
